(function(){
const q=new URLSearchParams(location.search);
try{const saved=JSON.parse(sessionStorage.getItem('incentive-navigation-state')||'null');if(saved){for(const [name,list] of [['fields',fields],['configs',configs],['programs',programs],['entityMappings',entityMappings]])if(Array.isArray(saved[name]))list.splice(0,list.length,...saved[name]);if(configs.length){selected=0;draft=structuredClone(configs[0]);}}}catch{}
function persist(){try{sessionStorage.setItem('incentive-navigation-state',JSON.stringify({fields,configs,programs,entityMappings}));sessionStorage.setItem('payout-shared-registry',JSON.stringify({fields,mappings:entityMappings.filter(m=>m.enabled).map(m=>({lob:m.lob,entity:m.entity}))}));}catch{}}
function link(label,target,active=false){return `<a class="menu-link${active?' active':''}" ${active?'aria-current="page"':''} href="${target}">${label}</a>`}
function payoutURL(page){const m=role==='admin'?adminMapping():managerMapping();return 'payouts.html?'+new URLSearchParams({role:role==='admin'?'admin':'manager',view:page,lob:m.lob,entity:m.entity}).toString()}
function group(name,body){return `<details class="menu-group" open><summary>${name}</summary><div>${body}</div></details>`}
const originalNav=navRole;
navRole=function(){originalNav();document.querySelectorAll('aside>[data-nav]').forEach(n=>n.remove());let nav=document.getElementById('engine-nav');if(!nav){nav=document.createElement('nav');nav.id='engine-nav';nav.className='engine-nav';nav.setAttribute('aria-label','Workspace navigation');document.getElementById('roleSwitch').after(nav)}if(role==='admin'){nav.innerHTML=group('Registry',link('Unit',payoutURL('units'))+`<button class="menu-link ${currentView==='registry'?'active':''}" data-local-page="registry">Keys</button>`)+`<button class="menu-link ${currentView==='config'?'active':''}" data-local-page="config">Incentive Config</button>`+group('Payout Config',link('Config',payoutURL('structures')));}else if(role==='manager'){nav.innerHTML=`<button class="menu-link active" data-local-page="manager">Incentive Config</button>`+group('Payout Config',link('Create template',payoutURL('templates'))+link('Map template to users',payoutURL('users')));}else nav.innerHTML='<a class="menu-link active" href="index.html?role=entity">Incentives</a><a class="menu-link" href="entity-payouts.html">Payouts</a>';};
document.addEventListener('click',e=>{const b=e.target.closest('[data-local-page]');if(b){currentView=b.dataset.localPage;if(role==='manager')programEdit=null;render();}if(e.target.closest('a[href^="payouts.html"]'))persist();});window.addEventListener('pagehide',persist);
if(['admin','manager','entity'].includes(q.get('role')))role=q.get('role');if(role==='admin')currentView=q.get('view')==='config'?'config':'registry';else if(role==='manager')currentView='manager';if(q.get('lob')){const m=entityMappings.find(m=>m.enabled&&m.lob===q.get('lob')&&m.entity===q.get('entity'));if(m){if(role==='admin')adminMappingId=m.id;else if(role==='manager')managerMappingId=m.id;}}
render();
})();
